// findWorktreeRootByWalking returns the nearest ancestor of start containing a
// .git entry. The entry may be a directory (ordinary checkout) or a file (a
// linked worktree's gitlink), and either marks a worktree root.
func findWorktreeRootByWalking(start string) (string, bool) {
	if start == "" {
		return "", false
	}
	dir, err := filepath.Abs(start)
	if err != nil {
		return "", false
	}
	for {
		if _, err := os.Lstat(filepath.Join(dir, ".git")); err == nil {
			return dir, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false // reached the filesystem root
		}
		dir = parent
	}
}

